import { addMinutes, LocalDateTime } from "../time/localTime";
import { QuietHours } from "./quietHours";

/**
 * 알림 발송 시각 정책.
 * - 안내 대상 시각(출금·재출금)보다 lead 분 앞서 보낸다.
 * - 야간 방해 금지 구간에 걸리면 전날 저녁으로 당긴다.
 * 결과는 그대로 푸시 예약 시각이 된다.
 */
export class SendTimePolicy {
  constructor(private readonly quiet: QuietHours) {}

  sendAt(dueAt: LocalDateTime, leadMinutes: number): LocalDateTime {
    const nominal = addMinutes(dueAt, -leadMinutes);
    return this.quiet.pullBack(nominal);
  }
}
import { spawnSync } from "child_process";
import { LocalDateTime } from "../time/localTime";

export interface QueuedPush {
  ticket: string;
  at: LocalDateTime;
  device: string;
  tag: string;
}

export interface DeliveredPush {
  at: LocalDateTime;
  device: string;
  tag: string;
  message: string;
}

export class PushqError extends Error {
  constructor(readonly code: string, readonly exitStatus: number | null) {
    super(`pushq ${code} (exit ${exitStatus})`);
  }
}

/** 앱 푸시 예약 벤더 CLI(pushq 2.x) 래퍼 */
export class PushqClient {
  constructor(private readonly bin: string, private readonly home: string) {}

  private run(args: string[]): string {
    const r = spawnSync(this.bin, args, {
      encoding: "utf8",
      env: { ...process.env, PUSHQ_HOME: this.home },
    });
    if (r.error) throw r.error;
    if (r.status !== 0) {
      const code = /E\d+/.exec(r.stderr)?.[0] ?? "E?";
      throw new PushqError(code, r.status);
    }
    return r.stdout;
  }

  /** 지정 시각 발송을 예약하고 티켓 번호를 돌려준다. */
  schedule(device: string, at: LocalDateTime, tag: string, message: string): string {
    const out = this.run(["schedule", "--to", device, "--at", at, "--tag", tag, message]);
    const m = /^ticket (T\d+)$/m.exec(out);
    if (!m) throw new PushqError("unparsed-output", 0);
    return m[1];
  }

  cancel(ticket: string): void {
    this.run(["cancel", ticket]);
  }

  /** 벤더 시계를 until 까지 진행시켜 그 사이 예약분을 내보낸다. */
  advance(until: LocalDateTime): number {
    const out = this.run(["run", "--until", until]);
    const m = /^delivered (\d+)$/m.exec(out);
    if (!m) throw new PushqError("unparsed-output", 0);
    return Number(m[1]);
  }

  queued(device?: string): QueuedPush[] {
    const out = this.run(device ? ["list", "--to", device] : ["list"]);
    return rows(out).map(([ticket, at, dev, tag]) => ({ ticket, at, device: dev, tag }));
  }

  delivered(device?: string): DeliveredPush[] {
    const out = this.run(device ? ["log", "--to", device] : ["log"]);
    return rows(out).map(([at, dev, tag, ...msg]) => ({ at, device: dev, tag, message: msg.join("\t") }));
  }
}

function rows(out: string): string[][] {
  return out
    .split("\n")
    .filter((l) => l !== "")
    .map((l) => l.split("\t"));
}
usage:
  pushq schedule --to <device> --at <YYYY-MM-DDTHH:MM:SS> [--tag <tag>] <message>
  pushq send --to <device> [--tag <tag>] <message>
  pushq list [--to <device>]          print <ticket>TAB<at>TAB<device>TAB<tag>
  pushq run --until <YYYY-MM-DDTHH:MM:SS>
  pushq log [--to <device>]           print <at>TAB<device>TAB<tag>TAB<message>
  pushq cancel <ticket>
limits: device 1..64, tag 0..64, message 1..512 bytes
env: PUSHQ_HOME (state directory, required)
# messages
ok   - money and merchant names are formatted for one push line
ok   - reminder texts mention merchant, amount and withdrawal time
ok   - reminder keys and device tokens are stable
all passed
# reminders.e2e
FAIL - every autopay customer gets the withdrawal reminder in time on billing day: reminders not delivered: expected [], got ["M1001 재출금 안내","M1003 출금 예정","M1004 출금 예정"]
ok   - customers who turned pushes off are skipped and counted
ok   - planning the same day twice does not double-book, and cancelled contracts stay quiet
1 failed
# time
ok   - minute arithmetic crosses days, months and leap days
ok   - local time validation rejects impossible dates
ok   - quiet hours pull a reminder back to the previous evening
all passed

